function isExcludedArticle(a){const names=(a?.f?.name||'')+' '+(a?.f?.publisher||'');if(/taipei\\s*times|台北時報/i.test(names))return true;return [a?.url,a?.publisherUrl].some(value=>{let decoded=String(value||'');for(let i=0;i<2;i++){try{decoded=decodeURIComponent(decoded)}catch{break}}return /(?:^|[/.?=&])(?:www\\.)?taipeitimes\\.com(?:[/:?&#]|$)/i.test(decoded)})}
