function updateSourceOptions(){
  const selected = $('source').value;
  $('source').replaceChildren(new Option('所有來源',''));
  for (const f of feeds) $('source').add(new Option(f.name + (f.disabled ? '（已停用）' : ''), f.id));
  if (feeds.some(f => String(f.id) === selected)) $('source').value = selected;
}
async function load(){
  if (busy) return;
  busy = true;
  $('refresh').disabled = true;
  try {
    const response = await fetch('/api/sources', {cache:'no-store'});
    if (!response.ok) throw Error('暫時無法讀取來源維護狀態');
    maintenance = await response.json();
    feeds.splice(0, feeds.length, ...maintenance.feeds);
    updateSourceOptions();
    const active = feeds.filter(f => !f.disabled);
    const activeIds = new Set(active.map(f => f.id));
    items = items.filter(a => activeIds.has(a.f.id));
    status = {};
    render();
    await Promise.all(active.map(async f => {
      try {
        const response = await fetch('/api/feed?id='+f.id+'&v=source-health');
        if (response.status === 410) {
          f.disabled = true;
          items = items.filter(a => a.f.id !== f.id);
          return;
        }
        if (!response.ok) throw Error((await response.text()).slice(0,140));
        const batch = parse(await response.text(), {...f,index:response.headers.get('X-News-Index')||''});
        items = items.filter(a => a.f.id !== f.id).concat(batch);
        status[f.id] = {ok:true,count:batch.length};
      } catch (error) {
        status[f.id] = {ok:false,error:error.message};
      }
    }));
    last = new Date();
  } catch (error) {
    maintenance = {error:error.message};
  } finally {
    busy = false;
    $('refresh').disabled = false;
    render();
  }
}
for(const r of [...new Set(feeds.map(f=>f.region))]) $('region').add(new Option(r,r));
