async function readRSS(url){const r=await fetch(String(url),{headers:{'Accept':'application/rss+xml, application/atom+xml, application/xml, text/xml','User-Agent':'WorldwireRSS/1.0'},signal:AbortSignal.timeout(12000),cf:{cacheTtl:240,cacheEverything:true}});if(!r.ok)throw Error('上游 HTTP '+r.status);const bytes=await r.arrayBuffer();let text=new TextDecoder('utf-8').decode(bytes);const encoding=text.match(/encoding=["']([^"']+)/i)?.[1];if(encoding&&!/^utf-?8$/i.test(encoding))text=new TextDecoder(encoding).decode(bytes);text=text.replace(/encoding=(["'])[^"']+\1/i,'encoding="UTF-8"');if(text.length>3000000)throw Error('來源資料過大');if(!/<(?:rss|feed|rdf:RDF)\b/i.test(text))throw Error('來源未提供 RSS');return text}
const CHECK_INTERVAL = 15 * 60 * 1000;
const CHECK_SHARDS = 24;
const WEEKLY_CRON = '0 1 * * MON';

function managedSource(feed) {
  return !feed.search && feed.category !== '智庫';
}

function hasReadableNews(xml) {
  const entries = /<(?:[\w-]+:)?(item|entry)\b[^>]*>([\s\S]*?)<\/(?:[\w-]+:)?\1\s*>/gi;
  for (const [, , body] of xml.matchAll(entries)) {
    const title = body.match(/<(?:[\w-]+:)?title\b[^>]*>([\s\S]*?)<\/(?:[\w-]+:)?title\s*>/i)?.[1];
    if (!title?.replace(/<!\[CDATA\[|\]\]>|<[^>]*>/g, '').trim()) continue;
    const link = /<(?:[\w-]+:)?(?:link|guid)\b[^>]*(?:href\s*=\s*["']https?:\/\/|>\s*(?:<!\[CDATA\[\s*)?https?:\/\/)/i;
    if (link.test(body)) return true;
  }
  return false;
}

async function probeSource(feed) {
  try {
    const xml = await readRSS(feed.url);
    if (!hasReadableNews(xml)) return 'RSS 沒有可收錄的標題與文章網址';
    return null;
  } catch (error) {
    return String(error.message).slice(0, 140);
  }
}

async function sourceCatalog(db) {
  const results = db ? (await db.prepare('SELECT * FROM source_health').all()).results : [];
  const states = new Map(results.map(row => [row.feed_url, row]));
  const activated = new Set(results.map(row => row.replacement).filter(Boolean));
  const visible = feeds.concat(reserveFeeds.filter(feed => activated.has(feed.url)));
  return {
    managed: Boolean(db),
    weekly: states.get('@weekly')?.checked_at ?? null,
    feeds: visible.map(feed => {
      const row = states.get(feed.url);
      const replacement = reserveFeeds.find(candidate => candidate.url === row?.replacement);
      return {
        ...feed,
        failures: row?.failures ?? 0,
        checkedAt: row?.checked_at ?? null,
        disabled: (row?.failures ?? 0) >= 3,
        failureReason: row?.reason ?? null,
        replacement: replacement?.name ?? null
      };
    })
  };
}

async function checkSources(db, scheduledTime) {
  const catalog = await sourceCatalog(db);
  const slot = Math.floor(scheduledTime / CHECK_INTERVAL);
  const due = catalog.feeds.filter(feed =>
    managedSource(feed) && !feed.disabled &&
    feed.id % CHECK_SHARDS === slot % CHECK_SHARDS &&
    (feed.checkedAt ?? 0) < scheduledTime
  );
  const results = await Promise.all(due.map(async feed => ({
    feed,
    reason: await probeSource(feed)
  })));
  if (results.length === 0) return;
  await db.batch(results.map(({feed, reason}) => db.prepare(
    `INSERT INTO source_health (feed_url, failures, checked_at, reason)
     VALUES (?1, ?2, ?3, ?4)
     ON CONFLICT(feed_url) DO UPDATE SET
       failures = CASE WHEN excluded.failures = 0 THEN 0 ELSE source_health.failures + 1 END,
       checked_at = excluded.checked_at,
       reason = excluded.reason
     WHERE source_health.failures < 3 AND source_health.checked_at < excluded.checked_at`
  ).bind(feed.url, reason ? 1 : 0, scheduledTime, reason)));
}

async function reviewReplacements(db, scheduledTime) {
  const catalog = await sourceCatalog(db);
  if (catalog.weekly !== null && catalog.weekly >= scheduledTime) return;
  const used = new Set(catalog.feeds.map(feed => feed.url));
  const attempted = new Set();
  for (const failed of catalog.feeds.filter(feed => feed.disabled && !feed.replacement)) {
    const candidates = reserveFeeds.filter(feed =>
      feed.region === failed.region && !used.has(feed.url) && !attempted.has(feed.url)
    );
    candidates.sort((a,b) => Number(b.lang === failed.lang) - Number(a.lang === failed.lang));
    for (const candidate of candidates) {
      attempted.add(candidate.url);
      if (await probeSource(candidate)) continue;
      const result = await db.prepare(
        `UPDATE source_health SET replacement = ?1
         WHERE feed_url = ?2 AND failures >= 3 AND replacement IS NULL
         AND NOT EXISTS (SELECT 1 FROM source_health WHERE replacement = ?1)`
      ).bind(candidate.url, failed.url).run();
      if (result.meta.changes) used.add(candidate.url);
      break;
    }
  }
  await db.prepare(
    `INSERT INTO source_health (feed_url, checked_at) VALUES ('@weekly', ?1)
     ON CONFLICT(feed_url) DO UPDATE SET checked_at = MAX(checked_at, excluded.checked_at)`
  ).bind(scheduledTime).run();
}

async function serveFeed(requestUrl, db) {
  const raw = requestUrl.searchParams.get('id');
  const id = raw !== null && /^\d+$/.test(raw) ? Number(raw) : -1;
  const feed = feeds[id] ?? reserveFeeds.find(candidate => candidate.id === id);
  if (!feed || (!db && id >= 1000)) return new Response('Unknown source', {status:400});
  try {
    if (db) {
      const state = await db.prepare(
        `SELECT COALESCE((SELECT failures FROM source_health WHERE feed_url = ?1), 0) AS failures,
                EXISTS(SELECT 1 FROM source_health WHERE replacement = ?1) AS activated`
      ).bind(feed.url).first();
      if (id >= 1000 && !state.activated) return new Response('Unknown source', {status:400});
      if (state.failures >= 3) {
        return new Response('連續三次檢查失敗，來源已停用', {status:410});
      }
    }
    let text;
    let index = feed.search ? 'google' : '';
    try {
      text = await readRSS(feed.url);
    } catch (error) {
      if (!feed.fallback) throw error;
      text = await readRSS(feed.fallback);
      index = 'bing';
    }
    return new Response(text, {headers:{
      'Content-Type':'application/xml; charset=utf-8',
      'Cache-Control':db ? 'no-store' : 'public, max-age=240',
      'X-Content-Type-Options':'nosniff',
      'X-News-Index':index
    }});
  } catch (error) {
    return new Response('來源暫時無法連線：'+error.message, {status:502});
  }
}

export default {
  async scheduled(controller, env) {
    if (!env.SOURCE_HEALTH) throw Error('SOURCE_HEALTH binding missing');
    if (controller.cron === WEEKLY_CRON) {
      await reviewReplacements(env.SOURCE_HEALTH, controller.scheduledTime);
    } else {
      await checkSources(env.SOURCE_HEALTH, controller.scheduledTime);
    }
  },
  async fetch(request, env) {
    const url = new URL(request.url);
    const db = env?.SOURCE_HEALTH;
    if (url.pathname === '/api/feed') return serveFeed(url, db);
    if (url.pathname === '/api/sources') {
      try {
        return Response.json(await sourceCatalog(db), {headers:{'Cache-Control':'no-store'}});
      } catch {
        return Response.json({error:'暫時無法讀取來源狀態'}, {status:503});
      }
    }
    if (url.pathname !== '/') return new Response('Not found', {status:404});
    return new Response(html,{headers:{
      'Content-Type':'text/html; charset=utf-8',
      'X-Content-Type-Options':'nosniff',
      'Referrer-Policy':'no-referrer',
      'Content-Security-Policy':"default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; frame-ancestors 'none'"
    }});
  }
};
